const inputItems = $input.all();
const validHosts = ['daft.ie', 'rent.ie', 'myhome.ie'];
const areaTerms = [
  'Dublin City Centre', 'City Centre', 'Temple Bar', 'Smithfield', 'Stoneybatter',
  'Phibsborough', 'Drumcondra', 'Phibsboro', 'Rathmines', 'Ranelagh', 'Rathgar',
  "Harold's Cross", 'Portobello', 'Grand Canal Dock', 'Ballsbridge', 'Sandymount',
  'Clontarf', 'Raheny', 'Howth', 'Malahide', 'Portmarnock', 'Swords', 'Baldoyle',
  'Donaghmede', 'Coolock', 'Artane', 'Glasnevin', 'Finglas', 'Ballymun',
  'Castleknock', 'Blanchardstown', 'Clonsilla', 'Lucan', 'Palmerstown',
  'Clondalkin', 'Tallaght', 'Citywest', 'Walkinstown', 'Crumlin', 'Kimmage',
  'Terenure', 'Rathfarnham', 'Dundrum', 'Stillorgan', 'Sandyford', 'Blackrock',
  'Dun Laoghaire', 'Dún Laoghaire', 'Cabinteely', 'Leopardstown', 'Bray',
  'Greystones', 'Balbriggan', 'Skerries', 'Rush', 'Lusk', 'Donabate', 'Maynooth',
  'Leixlip', 'Celbridge', 'Dublin 1', 'Dublin 2', 'Dublin 3', 'Dublin 4',
  'Dublin 5', 'Dublin 6', 'Dublin 6W', 'Dublin 7', 'Dublin 8', 'Dublin 9',
  'Dublin 10', 'Dublin 11', 'Dublin 12', 'Dublin 13', 'Dublin 14', 'Dublin 15',
  'Dublin 16', 'Dublin 17', 'Dublin 18', 'Dublin 20', 'Dublin 22', 'Dublin 24',
  'County Dublin', 'Co. Dublin', 'Dublin'
];
const centralTerms = [
  'city centre','temple bar','smithfield','stoneybatter','phibsborough','portobello',
  'dublin 1','dublin 2','dublin 7','dublin 8','dublin 6','dublin 4','rathmines',
  'ranelagh','drumcondra','grand canal dock','harold\'s cross'
];

function decodeEntities(s = '') {
  return String(s)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));
}
function stripHtml(s = '') {
  return decodeEntities(String(s)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')).trim();
}
function esc(s = '') {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
function getSource(url) {
  const host = new URL(url).hostname.toLowerCase().replace(/^www\./, '');
  if (host.endsWith('daft.ie')) return 'Daft.ie';
  if (host.endsWith('rent.ie')) return 'Rent.ie';
  if (host.endsWith('myhome.ie')) return 'MyHome.ie';
  return host;
}
function canonicalListingUrl(raw) {
  let href = decodeEntities(raw || '').trim();
  href = href.replace(/^\s+|\s+$/g, '');
  try {
    const u = new URL(href);
    const host = u.hostname.toLowerCase().replace(/^www\./, '');
    if (!validHosts.some(d => host === d || host.endsWith('.' + d))) return null;
    const path = u.pathname.toLowerCase();
    // Ignore accounts, searches, alerts and site-wide/navigation links. Only listing-like links.
    if (/login|register|saved-search|saved_search|unsubscribe|privacy|terms|contact|about|help|newsletter|search\/?$/.test(path)) return null;
    if (!/(for-rent|houses-to-let|apartments-to-let|rentals?|to-let|lettings|property|house|apartment|flat|residential|\/rent\/)/i.test(path)) return null;
    u.hash = '';
    ['utm_source','utm_medium','utm_campaign','utm_content','utm_term','fbclid','gclid'].forEach(k => u.searchParams.delete(k));
    return u.toString();
  } catch (e) {
    return null;
  }
}
function detectArea(text, wholeEmailText) {
  const hay = (' ' + String(text || '').toLowerCase() + ' ');
  const orderedAreaTerms = [...areaTerms].sort((a, b) => b.length - a.length);
  for (const term of orderedAreaTerms) {
    const t = term.toLowerCase();
    if (hay.includes(t)) return term;
  }
  // Some alert emails have a single Dublin-specific search heading but a very short property card.
  const global = String(wholeEmailText || '').toLowerCase();
  if (/(dublin|temple bar|smithfield|rathmines|ranelagh|swords|malahide|tallaght|lucan|clontarf|dun laoghaire|dún laoghaire)/i.test(global)) return 'Dublin / nearby area';
  return '';
}
function detectPrice(text) {
  const matches = String(text || '').match(/€\s?\d[\d,.]*(?:\s?(?:per\s?month|monthly|\/month|p\.?m\.?|a\s?month|per\s?week|weekly|a\s?week))?/ig);
  if (!matches || !matches.length) return '';
  // Prefer the first price that looks like an advertised rent.
  return matches[0].replace(/\s+/g, ' ').trim();
}
function deriveTitle(anchorText, context, url) {
  let title = stripHtml(anchorText || '');
  if (title.length > 4 && !/^(view|view property|view listing|read more|more details|click here|apply now|contact agent|find out more)$/i.test(title)) {
    return title.slice(0, 140);
  }
  const pathPart = new URL(url).pathname.split('/').filter(Boolean).pop() || '';
  const slugTitle = decodeURIComponent(pathPart).replace(/[-_]+/g, ' ').replace(/\.(html?|php)$/i, '').trim();
  if (slugTitle && !/^\d{4,}$/.test(slugTitle) && slugTitle.length > 4) return slugTitle.slice(0, 140);
  const withoutPrice = String(context || '').replace(/€\s?\d[\d,.]*/g, ' ');
  const words = stripHtml(withoutPrice).split(/\s+/).filter(Boolean);
  return (words.slice(0, 12).join(' ') || 'Rental listing').slice(0, 140);
}
function slug(s) {
  return String(s || '').toLowerCase().replace(/https?:\/\/\S+/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
}
function getPriority(listing) {
  const l = `${listing.area} ${listing.title}`.toLowerCase();
  const central = /city centre|temple bar|smithfield|stoneybatter|phibsborough|portobello|grand canal dock|harold's cross|rathmines|ranelagh|drumcondra|\bdublin\s*(?:1|2|4|6|7|8)\b/i;
  return central.test(l) ? 0 : 1;
}

const listings = new Map();
let alertEmailsScanned = 0;
for (const item of inputItems) {
  const j = item.json || {};
  const subject = String(j.subject || j.Subject || 'Rental alert');
  const html = String(j.html || j.textHtml || j.htmlBody || '');
  const plain = String(j.text || j.textPlain || j.snippet || '');
  if (!j.id && !html && !plain) continue;
  alertEmailsScanned++;
  const wholeText = (stripHtml(html) + ' ' + plain + ' ' + subject).trim();
  const candidates = [];
  if (html) {
    const anchorRe = /<a\b[^>]*href\s*=\s*(?:"([^"]+)"|'([^']+)'|([^\s>]+))[^>]*>([\s\S]*?)<\/a>/gi;
    let match;
    while ((match = anchorRe.exec(html)) !== null) {
      const rawUrl = match[1] || match[2] || match[3] || '';
      const url = canonicalListingUrl(rawUrl);
      if (!url) continue;
      const anchorText = stripHtml(match[4] || '');
      const start = Math.max(0, match.index - 900);
      const end = Math.min(html.length, match.index + match[0].length + 900);
      const context = stripHtml(html.slice(start, end));
      candidates.push({ url, anchorText, context });
    }
  }
  // Plain-text fallback for alerts where an HTML part is absent.
  if (!candidates.length && plain) {
    const urlRe = /https?:\/\/[^\s<>"']+/gi;
    let match;
    while ((match = urlRe.exec(plain)) !== null) {
      const url = canonicalListingUrl(match[0].replace(/[),.;]+$/, ''));
      if (!url) continue;
      const context = plain.slice(Math.max(0, match.index - 350), Math.min(plain.length, match.index + 600));
      candidates.push({ url, anchorText: '', context });
    }
  }

  for (const c of candidates) {
    const context = `${c.anchorText} ${c.context}`;
    const lower = context.toLowerCase();
    // Don't include room-only/shared-accommodation adverts; keep full homes and self-contained studios.
    if (/\b(room\s+to\s+rent|single\s+room|shared\s+room|roomshare|bedspace|renting\s+a\s+room)\b/i.test(context)) continue;
    const area = detectArea(context, wholeText);
    if (!area) continue;
    const price = detectPrice(context) || detectPrice(wholeText);
    const title = deriveTitle(c.anchorText, context, c.url);
    let bedrooms = '';
    const bedMatch = context.match(/\b(\d+)\s*(?:bed(?:room)?s?|beds)\b/i);
    if (bedMatch) bedrooms = `${bedMatch[1]} bed`;
    let source = 'Property website';
    try { source = getSource(c.url); } catch (e) {}
    const received = j.date ? new Date(j.date).toLocaleString('en-IE', { timeZone: 'Europe/Dublin', dateStyle: 'medium', timeStyle: 'short' }) : '';
    const normTitle = slug(title);
    const semanticKey = `${normTitle}|${slug(price)}|${slug(area)}`;
    const urlKey = c.url.toLowerCase();
    const key = (normTitle.length > 8 && price) ? semanticKey : urlKey;
    if (!listings.has(key)) {
      listings.set(key, { title, url: c.url, price, area, bedrooms, source, received, priority: 1 });
    }
  }
}

const results = [...listings.values()];
for (const l of results) l.priority = getPriority(l);
results.sort((a, b) => a.priority - b.priority || a.area.localeCompare(b.area) || a.title.localeCompare(b.title));
const dateLabel = new Intl.DateTimeFormat('en-IE', { timeZone: 'Europe/Dublin', dateStyle: 'full' }).format(new Date());
const timeLabel = new Intl.DateTimeFormat('en-IE', { timeZone: 'Europe/Dublin', hour: '2-digit', minute: '2-digit' }).format(new Date());
let html = `<!doctype html><html><body style="font-family:Arial,sans-serif;color:#202124;line-height:1.45;max-width:800px;margin:0 auto"><div style="background:#16324f;color:#fff;padding:22px 24px;border-radius:12px 12px 0 0"><div style="font-size:12px;letter-spacing:1.5px;text-transform:uppercase;opacity:.85">Dublin Rental Radar</div><h1 style="font-size:24px;margin:8px 0 4px">Your morning rental digest</h1><div>${esc(dateLabel)} · generated at ${esc(timeLabel)} (Ireland time)</div></div><div style="padding:20px 24px;border:1px solid #e4e7eb;border-top:0;border-radius:0 0 12px 12px"><p style="font-size:16px"><strong>${results.length}</strong> matching listing(s) found from <strong>${alertEmailsScanned}</strong> rental-alert email(s) received in the last 24 hours.</p>`;
if (results.length) {
  html += `<p style="color:#5f6368;font-size:13px">City-centre and central-neighbourhood matches are shown first. Listings are collected from your own portal alerts; the price and details are extracted from email content when available.</p>`;
  for (const l of results) {
    html += `<div style="border:1px solid #e4e7eb;border-radius:10px;padding:15px 16px;margin:12px 0;background:#fff"><div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start"><div style="font-weight:700;font-size:17px">${esc(l.title)}</div><div style="font-weight:700;font-size:18px;white-space:nowrap;color:#176b45">${esc(l.price || 'Price not detected')}</div></div><div style="color:#444;margin:7px 0">📍 ${esc(l.area)}${l.bedrooms ? ' · ' + esc(l.bedrooms) : ''}</div><div style="font-size:12px;color:#697078;margin-bottom:12px">Source: ${esc(l.source)}${l.received ? ' · Alert received: ' + esc(l.received) : ''}</div><a href="${esc(l.url)}" style="display:inline-block;background:#176b45;color:#fff;text-decoration:none;padding:9px 13px;border-radius:6px;font-weight:700">Open listing ↗</a></div>`;
  }
} else {
  html += `<div style="border:1px solid #e4e7eb;border-radius:10px;padding:18px;background:#f8fafc"><h2 style="margin:0 0 8px;font-size:18px">No new matching listings extracted today</h2><p style="margin:0">This usually means there were no new matching portal alerts in the last 24 hours. If you know alert emails arrived, check that your Gmail filter applies the <strong>Rental-Alerts</strong> label and that the source emails include a Dublin/nearby area and a property link.</p></div>`;
}
html += `<hr style="border:0;border-top:1px solid #e4e7eb;margin:24px 0 14px"><p style="font-size:12px;color:#697078">Coverage depends on which property portals send alert emails to your Gmail account and the search areas selected in those alerts. This digest does not directly crawl websites. Always open the original advert to confirm availability, full rent, deposit, location and viewing instructions.</p></div></body></html>`;
return [{ json: { html, subject: `Dublin Rental Radar — ${results.length} new listing(s) — ${dateLabel}`, listingCount: results.length, alertEmailsScanned } }];
